{"path": "src/semver.js", "content": "// compareVersions(a, b) → -1, 0 or 1 following Semantic Versioning 2.0.0 precedence
// (including pre-release identifiers; build metadata after '+' is ignored).
export function compareVersions(a, b) {
  const va = parse(a);
  const vb = parse(b);
  for (let i = 0; i < 3; i++) {
    if (va.core[i] !== vb.core[i]) return va.core[i] < vb.core[i] ? -1 : 1;
  }
  return comparePrerelease(va.pre, vb.pre);
}

function parse(version) {
  const noBuild = version.split('+')[0];
  const dash = noBuild.indexOf('-');
  const core = dash === -1 ? noBuild : noBuild.slice(0, dash);
  const pre = dash === -1 ? [] : noBuild.slice(dash + 1).split('.');
  return { core: core.split('.').map(Number), pre };
}

const NUMERIC = /^\d+$/;

function comparePrerelease(pa, pb) {
  // A version without pre-release has higher precedence than one with it.
  if (pa.length === 0 || pb.length === 0) {
    if (pa.length === pb.length) return 0;
    return pa.length === 0 ? 1 : -1;
  }
  const n = Math.min(pa.length, pb.length);
  for (let i = 0; i < n; i++) {
    const x = pa[i];
    const y = pb[i];
    if (x === y) continue;
    const xn = NUMERIC.test(x);
    const yn = NUMERIC.test(y);
    if (xn && yn) {
      const bx = BigInt(x);
      const by = BigInt(y);
      if (bx !== by) return bx < by ? -1 : 1;
      continue;
    }
    if (xn) return -1; // numeric identifiers have lower precedence
    if (yn) return 1;
    return x < y ? -1 : 1; // ASCII lexical order
  }
  if (pa.length === pb.length) return 0;
  return pa.length < pb.length ? -1 : 1;
}
"}

